"""Pipeline parallel (AFAB schedule) training step for LLaMA models.

Each rank owns a contiguous, roughly balanced slice of the decoder layers.
All microbatches are forwarded first (activations kept alive), then all
microbatches are backwarded, exchanging hidden states / gradients between
neighbouring pipeline stages with point-to-point communication.
"""

import inspect

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F

__all__ = ["train_step_pipeline_afab"]


# --------------------------------------------------------------------------- #
# helpers
# --------------------------------------------------------------------------- #
def _rank_world():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank(), dist.get_world_size()
    return 0, 1


def _partition(num_layers, world_size, rank):
    """Roughly balanced contiguous partition of ``num_layers`` over stages."""
    base, rem = divmod(num_layers, world_size)
    counts = [base + (1 if i < rem else 0) for i in range(world_size)]
    start = sum(counts[:rank])
    return start, start + counts[rank]


def _run_ops(ops):
    """Execute a list of P2POps, preferring the batched API."""
    if not ops:
        return
    try:
        reqs = dist.batch_isend_irecv(ops)
        for req in reqs:
            req.wait()
    except Exception:  # some backends (e.g. gloo) may not coalesce p2p ops
        reqs = [op.op(op.tensor, op.peer) for op in ops]
        for req in reqs:
            req.wait()


def _send_recv(send_tensor=None, send_to=None, recv_shape=None, recv_from=None,
               device=None, dtype=None):
    """Symmetric p2p exchange; returns the received tensor (or None)."""
    ops = []
    recv_tensor = None
    if recv_shape is not None and recv_from is not None:
        recv_tensor = torch.empty(recv_shape, device=device, dtype=dtype, requires_grad=True)
        ops.append(dist.P2POp(dist.irecv, recv_tensor, recv_from))
    if send_tensor is not None and send_to is not None:
        send_tensor = send_tensor.to(device=device, dtype=dtype).contiguous()
        ops.append(dist.P2POp(dist.isend, send_tensor, send_to))
    _run_ops(ops)
    return recv_tensor


def _call(module, **kwargs):
    """Call a HF module, dropping kwargs unsupported by the installed version."""
    try:
        params = inspect.signature(module.forward).parameters
        if not any(p.kind is inspect.Parameter.VAR_KEYWORD for p in params.values()):
            kwargs = {k: v for k, v in kwargs.items() if k in params}
    except (TypeError, ValueError):
        pass
    try:
        return module(**kwargs)
    except TypeError:
        kwargs.pop("use_cache", None)
        return module(**kwargs)


def _hidden(out):
    if torch.is_tensor(out):
        return out
    for name in ("last_hidden_state", "logits"):
        val = getattr(out, name, None)
        if val is not None:
            return val
    return out[0]


def _decoder(model):
    get_decoder = getattr(model, "get_decoder", None)
    if callable(get_decoder):
        dec = get_decoder()
        if dec is not None:
            return dec
    return model.model


def _broadcast_shapes(inputs, device):
    """Make the microbatch shapes known on every stage (rank 0 is authoritative)."""
    rank, world_size = _rank_world()
    local = []
    if inputs is not None:
        for x in inputs:
            if torch.is_tensor(x) and x.dim() >= 2:
                local.append((int(x.shape[0]), int(x.shape[1])))
    if world_size == 1:
        return local

    count = torch.tensor([len(local)], dtype=torch.long, device=device)
    dist.broadcast(count, src=0)
    n = int(count.item())
    shapes = torch.zeros((n, 2), dtype=torch.long, device=device)
    if rank == 0:
        shapes = torch.tensor(local, dtype=torch.long, device=device).reshape(n, 2)
    dist.broadcast(shapes, src=0)
    return [(int(s[0]), int(s[1])) for s in shapes]


# --------------------------------------------------------------------------- #
# main entry point
# --------------------------------------------------------------------------- #
def train_step_pipeline_afab(model, inputs, targets, device, dtype):
    """One training step with all-forward-all-backward pipeline parallelism.

    Returns the (microbatch-averaged) loss on the last stage, 0.0 elsewhere.
    """
    rank, world_size = _rank_world()
    is_first, is_last = rank == 0, rank == world_size - 1
    prev_rank, next_rank = rank - 1, rank + 1

    decoder = _decoder(model)
    all_layers = list(decoder.layers)
    start, end = _partition(len(all_layers), world_size, rank)

    hidden_size = getattr(model.config, "hidden_size", None)
    if hidden_size is None:
        hidden_size = decoder.config.hidden_size

    shapes = _broadcast_shapes(inputs, device)
    n_micro = len(shapes)
    if n_micro == 0:
        return 0.0
    act_shapes = [(mb, sl, hidden_size) for mb, sl in shapes]

    # ---- restrict this rank to its own layers (restored before returning) ---
    orig_layers, orig_norm = decoder.layers, getattr(decoder, "norm", None)
    decoder.layers = nn.ModuleList(all_layers[start:end])
    if not is_last and orig_norm is not None:
        decoder.norm = nn.Identity()

    total_loss = 0.0
    try:
        input_tensors, output_tensors = [], []

        # ------------------------------- forward ------------------------- #
        for i in range(n_micro):
            if is_first:
                input_tensor = None
                ids = inputs[i].to(device=device)
                stage_in = {"input_ids": ids}
            else:
                input_tensor = _send_recv(recv_shape=act_shapes[i], recv_from=prev_rank,
                                          device=device, dtype=dtype)
                stage_in = {"inputs_embeds": input_tensor}

            if is_last:
                logits = _hidden(_call(model, use_cache=False, **stage_in))
                tgt = targets[i].to(device=device)
                output_tensor = F.cross_entropy(
                    logits.float().reshape(-1, logits.shape[-1]), tgt.reshape(-1)
                ) / n_micro
                total_loss += float(output_tensor.detach())
            else:
                output_tensor = _hidden(_call(decoder, use_cache=False, **stage_in))
                output_tensor = output_tensor.to(device=device, dtype=dtype)
                _send_recv(send_tensor=output_tensor.detach(), send_to=next_rank,
                           device=device, dtype=dtype)

            input_tensors.append(input_tensor)
            output_tensors.append(output_tensor)

        # ------------------------------- backward ------------------------ #
        for i in range(n_micro):
            input_tensor, output_tensor = input_tensors[i], output_tensors[i]
            if is_last:
                grad_output = None
            else:
                grad_output = _send_recv(recv_shape=act_shapes[i], recv_from=next_rank,
                                         device=device, dtype=dtype)
                grad_output = grad_output.detach()

            torch.autograd.backward(output_tensor, grad_tensors=grad_output)

            if not is_first:
                grad_input = input_tensor.grad
                if grad_input is None:
                    grad_input = torch.zeros(act_shapes[i], device=device, dtype=dtype)
                _send_recv(send_tensor=grad_input, send_to=prev_rank,
                           device=device, dtype=dtype)
    finally:
        decoder.layers = orig_layers
        if orig_norm is not None:
            decoder.norm = orig_norm

    return total_loss

